    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 betAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (betAmount)); require(betAmount <= 1000000000000000000000000000000);
        require(betAmount > 0);
        require(address(this).balance >= betAmount);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(betAmount); if (__ESBMC_reverted()) return;

        c.wager{value: betAmount}(); if (__ESBMC_reverted()) return;

        assert(c.hasPlayerWagered(address(this)));
    }

    receive() external payable {}
}

