pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 betAmount) internal {
        betAmount = bound(betAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(betAmount > 0);
        vm.assume(address(this).balance >= betAmount);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(betAmount) {} catch { return; }
        try c.wager{value: betAmount}() {} catch { return; }
        assertTrue(c.hasPlayerWagered(address(this)));
    }

    function testFuzz_run(uint256 betAmount) public {
        _run(betAmount);
    }

    receive() external payable {}
}
